CREATE TABLE IF NOT EXISTS gis_phase376_datahub_sources (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),dataset_key TEXT NOT NULL UNIQUE,provider TEXT NOT NULL DEFAULT 'GRID3',catalog_url TEXT,download_url TEXT,format TEXT,status TEXT NOT NULL DEFAULT 'DISCOVERED',checksum TEXT,provenance JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());